constexpr std::size_t fivegluonfixed_color_1::parameter_count;
constexpr std::size_t fivegluonfixed_color_1::helicity_count;

const cdouble fivegluonfixed_color_1::constant_sqrt2 = std::sqrt(ldouble(2.0e0L));

fivegluonfixed_color_1::fivegluonfixed_color_1() : fivegluonfixed_color_1(default_parameters()) {}

fivegluonfixed_color_1::fivegluonfixed_color_1(const Parameters& values) {
  set_parameters(values);
}

fivegluonfixed_color_1::fivegluonfixed_color_1(const ldouble& value_GG)
  : fivegluonfixed_color_1(Parameters{{cdouble(value_GG)}}) {}

// Copies rebuild caches, so every sproduct points into its own process.
fivegluonfixed_color_1::fivegluonfixed_color_1(const fivegluonfixed_color_1& other) {
  widths_enabled = other.widths_enabled;
  set_parameters(other.parameters);
  if (other.momenta_ready) set_momenta(other.momenta);
}

fivegluonfixed_color_1& fivegluonfixed_color_1::operator=(const fivegluonfixed_color_1& other) {
  if (this != &other) {
    widths_enabled = other.widths_enabled;
    set_parameters(other.parameters);
    if (other.momenta_ready) set_momenta(other.momenta);
  }
  return *this;
}

fivegluonfixed_color_1::Parameters fivegluonfixed_color_1::default_parameters() {
  return Parameters{{
    cdouble(ldouble(1.117e0L), ldouble(0.0L)) // "GG"
  }};
}

fivegluonfixed_color_1::Spins fivegluonfixed_color_1::default_spins() {
  return Spins{{2, 2, 2, -2, -2}};
}

std::array<std::size_t, 2> fivegluonfixed_color_1::incoming_legs() {
  return {{0, 1}};
}

std::array<fivegluonfixed_color_1::Spins, fivegluonfixed_color_1::helicity_count>
fivegluonfixed_color_1::helicity_configurations() {
  return std::array<Spins, helicity_count>{{
    {{2, 2, 2, -2, -2}}
  }};
}

ldouble fivegluonfixed_color_1::incoming_spin_average() {
  return ldouble(1.0e0L);
}

ldouble fivegluonfixed_color_1::symmetry_factor() {
  return ldouble(1.66666666666666666666666e-1L);
}

void fivegluonfixed_color_1::initialize_products() {
  a45a = spinas::sproduct(::ANGLE, &p4, &p5);
  a13a = spinas::sproduct(::ANGLE, &p1, &p3);
  a15a = spinas::sproduct(::ANGLE, &p1, &p5);
  a23a = spinas::sproduct(::ANGLE, &p2, &p3);
  a24a = spinas::sproduct(::ANGLE, &p2, &p4);
}

void fivegluonfixed_color_1::set_parameters(const Parameters& values) {
  for (const auto& value : values) {
    if (!finite_complex(value)) {
      throw std::invalid_argument("Model parameters must be finite.");
    }
  }
  momenta_ready = false;
  all_point_cache_ready = false;
  summed_point_cache_ready = false;
  parameters = values;
  GG = parameters[0];

  // Recompute model-only factors once after parameter changes.
  parameter_factor_1_2 = (GG * GG * GG);
  parameter_factor_1 = cdouble(ldouble(0.0L), ldouble(-2.0e0L)) * constant_sqrt2 * parameter_factor_1_2;
  external_masses[0] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[1] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[2] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[3] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[4] = checked_mass(cdouble(ldouble(0.0L)));
  if ((external_masses[0] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p1 = spinas::particle(external_masses[0]);
  if ((external_masses[1] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p2 = spinas::particle(external_masses[1]);
  if ((external_masses[2] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p3 = spinas::particle(external_masses[2]);
  if ((external_masses[3] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p4 = spinas::particle(external_masses[3]);
  if ((external_masses[4] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p5 = spinas::particle(external_masses[4]);
  initialize_products();
}

void fivegluonfixed_color_1::set_widths_enabled(bool enabled) {
  if (widths_enabled == enabled) return;
  widths_enabled = enabled;
  momenta_ready = false;
  all_point_cache_ready = false;
  summed_point_cache_ready = false;
}

void fivegluonfixed_color_1::set_momenta(const Momenta& values) {
  const auto validation = validate_momenta(values, external_masses, incoming_legs());
  if (!validation.valid) throw std::invalid_argument(validation.message);
  momenta_ready = false;
  all_point_cache_ready = false;
  summed_point_cache_ready = false;
  momenta = values;

  // External particle momenta.
  p1.set_momentum(momenta[0].data());
  p2.set_momentum(momenta[1].data());
  p3.set_momentum(momenta[2].data());
  p4.set_momentum(momenta[3].data());
  p5.set_momentum(momenta[4].data());
  momenta_ready = true;
}

// Prepare only data used by the retained helicity contributions.
void fivegluonfixed_color_1::prepare_summed_point_cache() {
  if (summed_point_cache_ready) return;
  a13a.update();
  a15a.update();
  a23a.update();
  a24a.update();
  a45a.update();
  point_product_1 = a45a.v();
  point_product_2 = a13a.v();
  point_product_3 = a15a.v();
  point_product_4 = a23a.v();
  point_product_5 = a24a.v();
  summed_point_cache_ready = true;
}

// Individual amplitudes can lazily request the remaining helicities.
void fivegluonfixed_color_1::prepare_all_point_cache() {
  if (all_point_cache_ready) return;
  prepare_summed_point_cache();
  all_point_cache_ready = true;
}

void fivegluonfixed_color_1::set_momenta(const ldouble mom1[4], const ldouble mom2[4], const ldouble mom3[4],
  const ldouble mom4[4], const ldouble mom5[4]) {
  Momenta values;
  std::copy(mom1, mom1 + 4, values[0].begin());
  std::copy(mom2, mom2 + 4, values[1].begin());
  std::copy(mom3, mom3 + 4, values[2].begin());
  std::copy(mom4, mom4 + 4, values[3].begin());
  std::copy(mom5, mom5 + 4, values[4].begin());
  set_momenta(values);
}

cdouble fivegluonfixed_color_1::amp(const Spins& spins) {
  return amp(spins[0], spins[1], spins[2], spins[3], spins[4]);
}

// set_momenta(...) must be called before evaluating an amplitude.
cdouble fivegluonfixed_color_1::amp(const int& ds1, const int& ds2, const int& ds3, const int& ds4, const int&
  ds5) {
  if (!momenta_ready) throw std::logic_error("Call set_momenta before amp.");
  if (ds1 != -2 && ds1 != 2) throw std::invalid_argument("Invalid massless helicity.");
  if (ds2 != -2 && ds2 != 2) throw std::invalid_argument("Invalid massless helicity.");
  if (ds3 != -2 && ds3 != 2) throw std::invalid_argument("Invalid massless helicity.");
  if (ds4 != -2 && ds4 != 2) throw std::invalid_argument("Invalid massless helicity.");
  if (ds5 != -2 && ds5 != 2) throw std::invalid_argument("Invalid massless helicity.");
  prepare_all_point_cache();
  return amp_unchecked(ds1, ds2, ds3, ds4, ds5);
}

// Numerical kernel; public amp and spin_sum validate their inputs first.
cdouble fivegluonfixed_color_1::amp_unchecked(const int& ds1, const int& ds2, const int& ds3, const int& ds4,
  const int& ds5) {
  const unsigned long long helicity_key = (ds1 > 0 ? (1ULL << 0) : 0ULL) | (ds2 > 0 ? (1ULL << 1) : 0ULL) | (ds3
    > 0 ? (1ULL << 2) : 0ULL) | (ds4 > 0 ? (1ULL << 3) : 0ULL) | (ds5 > 0 ? (1ULL << 4) : 0ULL);
  switch (helicity_key) {

  case 7ULL: {
    return ((parameter_factor_1 * ((point_product_1 * point_product_1) * point_product_1))) /
      ((((point_product_2 * point_product_3) * point_product_4) * point_product_5));
  }
  default: throw std::invalid_argument("This exported process does not contain the selected helicities.");
  }
}

// Explicit spin and helicity sums.
ldouble fivegluonfixed_color_1::spin_sum() {
  ldouble result = 0;
  cdouble amplitude;
  if (!momenta_ready) throw std::logic_error("Call set_momenta before spin_sum.");
  prepare_all_point_cache();
  const int j1 = 2;
  const int j2 = 2;
  const int j3 = 2;
  const int j4 = -2;
  const int j5 = -2;
  amplitude = amp_unchecked(j1, j2, j3, j4, j5);
  result += std::norm(amplitude);
  return result;
}

ldouble fivegluonfixed_color_1::amp2() {
  // Initial-state average: 1/1.
  // Final-state identical-particle factor: 1/6.
  return spin_sum() / ldouble(6.0L);
}

