void fivegluonfixed_color_6::initialize_products() {
  a14a = spinas::sproduct(::ANGLE, &p1, &p4);
  a15a = spinas::sproduct(::ANGLE, &p1, &p5);
  a23a = spinas::sproduct(::ANGLE, &p2, &p3);
  a45a = spinas::sproduct(::ANGLE, &p4, &p5);
  s23s = spinas::sproduct(::SQUARE, &p2, &p3);
  a13a = spinas::sproduct(::ANGLE, &p1, &p3);
  a24a = spinas::sproduct(::ANGLE, &p2, &p4);
  a12a = spinas::sproduct(::ANGLE, &p1, &p2);
  a35a = spinas::sproduct(::ANGLE, &p3, &p5);
}

void fivegluonfixed_color_6::set_parameters(const Parameters& values) {
  for (const auto& value : values) {
    if (!finite_complex(value)) {
      throw std::invalid_argument("Model parameters must be finite.");
    }
  }
  momenta_ready = false;
  all_point_cache_ready = false;
  summed_point_cache_ready = false;
  parameters = values;
  GG = parameters[0];

  // Recompute model-only factors once after parameter changes.
  parameter_factor_1_2 = (GG * GG * GG);
  parameter_factor_1 = cdouble(ldouble(0.0L), ldouble(-2.0e0L)) * constant_sqrt2 * parameter_factor_1_2;
  external_masses[0] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[1] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[2] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[3] = checked_mass(cdouble(ldouble(0.0L)));
  external_masses[4] = checked_mass(cdouble(ldouble(0.0L)));
  if ((external_masses[0] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p1 = spinas::particle(external_masses[0]);
  if ((external_masses[1] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p2 = spinas::particle(external_masses[1]);
  if ((external_masses[2] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p3 = spinas::particle(external_masses[2]);
  if ((external_masses[3] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p4 = spinas::particle(external_masses[3]);
  if ((external_masses[4] == 0) != true) {
    throw std::invalid_argument(
      "Changing between massive and massless spin states requires re-exporting the process.");
  }
  p5 = spinas::particle(external_masses[4]);
  initialize_products();
}

void fivegluonfixed_color_6::set_widths_enabled(bool enabled) {
  if (widths_enabled == enabled) return;
  widths_enabled = enabled;
  momenta_ready = false;
  all_point_cache_ready = false;
  summed_point_cache_ready = false;
}

void fivegluonfixed_color_6::set_momenta(const Momenta& values) {
  const auto validation = validate_momenta(values, external_masses, incoming_legs());
  if (!validation.valid) throw std::invalid_argument(validation.message);
  momenta_ready = false;
  all_point_cache_ready = false;
  summed_point_cache_ready = false;
  momenta = values;

  // External particle momenta.
  p1.set_momentum(momenta[0].data());
  p2.set_momentum(momenta[1].data());
  p3.set_momentum(momenta[2].data());
  p4.set_momentum(momenta[3].data());
  p5.set_momentum(momenta[4].data());
  momenta_ready = true;
}

// Prepare only data used by the retained helicity contributions.
void fivegluonfixed_color_6::prepare_summed_point_cache() {
  if (summed_point_cache_ready) return;
  a12a.update();
  a13a.update();
  a14a.update();
  a15a.update();
  a23a.update();
  a24a.update();
  a35a.update();
  a45a.update();
  s23s.update();
  point_product_1 = a14a.v();
  point_product_2 = a15a.v();
  point_product_3 = a23a.v();
  point_product_4 = a45a.v();
  point_product_5 = s23s.v();
  point_product_6 = a13a.v();
  point_product_7 = a24a.v();
  point_product_8 = a12a.v();
  point_product_9 = a35a.v();
  point_factor_1 = ((point_product_4 * point_product_4) * point_product_4);
  point_factor_2 = (point_product_5 * point_product_5);
  summed_point_cache_ready = true;
}

// Individual amplitudes can lazily request the remaining helicities.
void fivegluonfixed_color_6::prepare_all_point_cache() {
  if (all_point_cache_ready) return;
  prepare_summed_point_cache();
  all_point_cache_ready = true;
}

